from pathlib import Path; import hashlib,zipfile; root=Path('/wheelhouse'); wheels=list(root.glob('*.whl')); assert len(wheels)==1; wheel=wheels[0]; assert wheel.name.startswith('psycopg2-2.9.13-'); z=zipfile.ZipFile(wheel); assert z.testzip() is None; assert not any('.libs/' in n or n.startswith('/') or '..' in Path(n).parts for n in z.namelist()); digest=hashlib.sha256(wheel.read_bytes()).hexdigest(); (root/'built-wheel.lock').write_text('psycopg2==2.9.13 --hash=sha256:'+digest+'\n');